    interactiveTips: ['استخدم نقطة «زِيَارَةٌ سِرِّيَّةٌ» للطريق، ونقطة «أَبُو بَكْرٍ» لأسباب الاختيار.', 'أعد تشغيل «لَمْ يُرِدْ أَنْ يَرَاهُ أَحَدٌ» واسأل: من الذي قد يرى؟', 'أبقِ الزيارة هادئة: يذكر الفصل الخوف، ولا يحدث خطر في الطريق.'],
    differentiation: { strugglingLearners: 'بطاقات الطريق مع بداياتها المشكولة: «فَكَّرَ فِي…»، «قَرَّرَ أَنْ…»، «عِنْدَمَا وَصَلَ إِلَى…»، «بَدَأَ يَسْأَلُ…».', fastFinishers: 'أعد سرد الفصل في ست جمل بـ«أولًا، ثم، عندما، وفي النهاية»، وأضف جملة بـ«لم يُرِدْ أن…» وجملة بـ«أنّ أبا بكر…».' },
    formativeAssessment: ['يرتّب الزيارة ترتيبًا صحيحًا.', 'يذكر سبب الزيارة من النص.', 'يستعمل الفعل مع حرفه ويضبط ما بعد «لم» و«أن» و«بدأ» و«أنّ».'],
